package com.fixit.dto; import jakarta.validation.constraints.*; import lombok.*; import java.math.BigDecimal;
@Data @NoArgsConstructor @AllArgsConstructor @Builder public class SecondHandListingRequest { @NotBlank(message="Seller name is required") @Size(min=2,max=255) private String sellerName; @NotBlank(message="Seller phone is required") @Pattern(regexp="^\\+?[0-9]{10,15}$",message="Invalid phone format") private String sellerPhone; @Email(message="Invalid email format") private String sellerEmail; @NotBlank(message="Product name is required") @Size(min=3,max=255) private String productName; @NotBlank(message="Condition is required") private String condition; @NotBlank(message="Detailed description is required") @Size(min=20,max=2000) private String detailedDescription; @NotNull(message="Expected price is required") @DecimalMin(value="0.01",message="Price must be greater than 0") private BigDecimal expectedPrice; }
